<div class="page-actions"><p class="muted">Kelola daftar pegawai yang dapat dicatat kehadirannya.</p><a class="btn btn-primary" href="<?= site_url('employees/new') ?>">＋ Tambah pegawai</a></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>NAMA PEGAWAI</th><th>JABATAN</th><th>TELEPON</th><th>AKUN STAFF</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach ($employees as $employee): ?><tr><td class="strong"><?= esc($employee['name']) ?></td><td><?= esc($employee['position']) ?></td><td><?= esc($employee['phone'] ?: '—') ?></td><td><?php if ($employee['staff_username']): ?><span class="badge badge-income"><?= esc($employee['staff_username']) ?></span><?php else: ?><span class="muted">Belum dibuat</span><?php endif ?></td><td><span class="badge <?= $employee['is_active'] ? 'badge-income' : 'badge-expense' ?>"><?= $employee['is_active'] ? 'Aktif' : 'Nonaktif' ?></span></td><td class="actions"><a class="text-link" href="<?= site_url('employees/' . $employee['id'] . '/edit') ?>">Ubah</a><?php if ($employee['is_active']): ?><form method="post" action="<?= site_url('employees/' . $employee['id'] . '/delete') ?>" onsubmit="return confirm('Nonaktifkan pegawai ini?')"><?= csrf_field() ?><button class="link-danger">Nonaktifkan</button></form><?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php if (! $employees): ?><div class="empty-state">Belum ada pegawai yang ditambahkan.</div><?php endif ?></div>
